  if(actions){actions.querySelectorAll('form').forEach(function(form){if(form.querySelector('input[name="decision"]'))form.style.display='none';});var reject=actions.querySelector('.js-reject');if(reject)reject.style.display='none';}
  if(!actions||!deleteActions[id])return;
  var form=document.createElement('form');form.method='post';form.action=deleteActions[id];form.style.display='inline';form.innerHTML='<input type="hidden" name="_token" value="'+csrf+'"><input type="hidden" name="_method" value="DELETE"><button class="btn btn-default btn-xs" type="submit"><i class="fa fa-trash text-red"></i> 删除</button>';
  form.addEventListener('submit',function(e){if(!confirm('确认删除这份广告费提报吗？删除后运营可以重新填写，原记录仍会保留在已删除记录中。'))e.preventDefault();});actions.appendChild(form);
 });
 document.querySelectorAll('.review-status').forEach(function(item){if(item.textContent.trim()==='已删除')item.classList.add('deleted');});
 document.querySelectorAll('.review-actions [data-target^="#fashion-review-"]').forEach(function(button){var target=button.getAttribute('data-target');button.removeAttribute('data-toggle');button.removeAttribute('data-target');button.classList.add('js-review-detail');button.setAttribute('data-detail-target',target);});
 document.addEventListener('click',function(e){var button=e.target.closest&&e.target.closest('.js-review-detail');if(!button)return;var detail=document.querySelector(button.getAttribute('data-detail-target')),body=document.getElementById('fashion-review-detail-body');if(!detail||!body)return;var page=detail.querySelector('.fashion-detail-page');body.innerHTML='';if(page)body.appendChild(page.cloneNode(true));jQuery('#fashion-review-detail-modal').modal('show');e.preventDefault();});
 document.addEventListener('click',function(e){var button=e.target.closest&&e.target.closest('.js-reject');if(!button)return;document.getElementById('fashion-reject-form').action=button.getAttribute('data-action');var detailModal=jQuery('#fashion-review-detail-modal'),rejectModal=jQuery('#fashion-reject-modal');if(detailModal.hasClass('in'))detailModal.one('hidden.bs.modal',function(){rejectModal.modal('show')}).modal('hide');else rejectModal.modal('show');});
 var selectAll=document.getElementById('fashion-select-all'),bulkForm=document.getElementById('fashion-bulk-review-form'),bulkCount=document.getElementById('fashion-bulk-count');
 function selected(){return Array.prototype.slice.call(document.querySelectorAll('.fashion-report-checkbox:checked'));}
 function refreshBulk(){var boxes=document.querySelectorAll('.fashion-report-checkbox'),count=selected().length;if(bulkCount)bulkCount.textContent='已选 '+count+' 份';if(selectAll){selectAll.checked=boxes.length>0&&count===boxes.length;selectAll.indeterminate=count>0&&count<boxes.length;}}
 if(selectAll)selectAll.addEventListener('change',function(){document.querySelectorAll('.fashion-report-checkbox').forEach(function(box){box.checked=selectAll.checked;});refreshBulk();});
 document.querySelectorAll('.fashion-report-checkbox').forEach(function(box){box.addEventListener('change',refreshBulk);});
 function submitBulk(decision){if(!bulkForm||selected().length===0){alert('请至少选择一条待审核报表。');return;}var reason='';if(decision==='rejected'){reason=prompt('请输入批量审核不通过的原因：','')||'';if(!reason.trim()){alert('审核不通过时必须填写原因。');return;}}else if(!confirm('确认批量通过已选择的 '+selected().length+' 份报表吗？'))return;document.getElementById('fashion-bulk-decision').value=decision;document.getElementById('fashion-bulk-reason').value=reason.trim();bulkForm.submit();}
 var approve=document.getElementById('fashion-bulk-approve'),reject=document.getElementById('fashion-bulk-reject');if(approve)approve.addEventListener('click',function(){submitBulk('approved');});if(reject)reject.addEventListener('click',function(){submitBulk('rejected');});refreshBulk();
})();
</script>
@endpush
